import React, { useState, useEffect, useCallback } from "react";
import api from "../utils/api";
import JobCard from "../components/JobCard";
import { useNavigate } from "react-router-dom";

export default function Jobs() {
  const [query, setQuery]       = useState("software developer");
  const [location, setLocation] = useState("remote");
  const [jobs, setJobs]         = useState([]);
  const [loading, setLoading]   = useState(false);
  const [fetching, setFetching] = useState(false);
  const [error, setError]       = useState("");
  const [msg, setMsg]           = useState("");
  const [totalInDb, setTotalInDb] = useState(null);
  const navigate = useNavigate();

  // Load all cached jobs from MongoDB on mount
  useEffect(() => {
    loadCachedJobs();
  }, []);

  const loadCachedJobs = async () => {
    setLoading(true);
    setError("");
    try {
      const res = await api.get("/fetched-jobs/all?limit=100");
      setJobs(res.data.jobs || []);
      setTotalInDb(res.data.total);
    } catch {
      setError("Failed to load jobs from database.");
    } finally {
      setLoading(false);
    }
  };

  // Search: hits cache first, only calls JSearch if cache miss
  const searchJobs = async () => {
    setFetching(true);
    setError("");
    setMsg("");
    try {
      const res = await api.get("/fetched-jobs", {
        params: { query, location, num_pages: 1, fetch_details: false },
      });
      setMsg(
        res.data.storage?.mongo_new_upserted > 0
          ? `Fetched ${res.data.total_stored} new jobs from JSearch and cached them.`
          : `Served ${res.data.total_stored} jobs from cache (no API call made).`
      );
      // Reload all from mongo to reflect new results
      const all = await api.get("/fetched-jobs/all?limit=100");
      setJobs(all.data.jobs || []);
      setTotalInDb(all.data.total);
    } catch (err) {
      setError(err.response?.data?.detail || "Search failed.");
    } finally {
      setFetching(false);
    }
  };

  const handleSkillGap = (job) => {
    navigate("/skill-gap", {
      state: {
        job_id: job.source_id,
        target_job_title: job.title,
        required_skills: job.required_skills || [],
      },
    });
  };

  return (
    <div>
      <div className="page-header">
        <h1>Browse Jobs</h1>
        <p>
          {totalInDb !== null ? (
            <><span className="text-accent">{totalInDb}</span> jobs cached in database — search fetches from cache first.</>
          ) : "Search and explore jobs. Results are cached in MongoDB to minimise API calls."}
        </p>
      </div>

      {/* Search bar */}
      <div className="card" style={{ marginBottom: 24 }}>
        <div className="flex wrap" style={{ gap: 12 }}>
          <input
            className="form-input"
            style={{ flex: 2, minWidth: 200 }}
            placeholder="Job title or keyword…"
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={e => e.key === "Enter" && searchJobs()}
          />
          <input
            className="form-input"
            style={{ flex: 1, minWidth: 140 }}
            placeholder="Location or 'remote'"
            value={location}
            onChange={e => setLocation(e.target.value)}
            onKeyDown={e => e.key === "Enter" && searchJobs()}
          />
          <button
            className="apply-btn"
            style={{ padding: "10px 24px", fontSize: 14 }}
            onClick={searchJobs}
            disabled={fetching}
          >
            {fetching ? "Searching…" : "Search"}
          </button>
        </div>
        <p className="text-muted text-sm" style={{ marginTop: 8 }}>
          💡 Results are served from MongoDB cache. JSearch API is only called on a cache miss.
        </p>
      </div>

      {msg   && <div className="alert alert-info"   style={{ marginBottom: 16 }}>{msg}</div>}
      {error && <div className="alert alert-error"  style={{ marginBottom: 16 }}>{error}</div>}

      {loading ? (
        <div className="spinner" />
      ) : jobs.length === 0 ? (
        <div className="empty-state">
          <h3>No jobs in database yet</h3>
          <p>Use the search above to fetch and cache jobs from JSearch.</p>
        </div>
      ) : (
        <>
          <div className="flex justify-between items-center" style={{ marginBottom: 16 }}>
            <h2>All cached jobs ({jobs.length})</h2>
            <button
              className="nav-btn ghost"
              style={{ fontSize: 13 }}
              onClick={loadCachedJobs}
            >
              Refresh list
            </button>
          </div>
          <div className="jobs-grid">
            {jobs.map((job, i) => (
              <JobCard
                key={job.source_id || i}
                job={job}
                onSkillGap={handleSkillGap}
              />
            ))}
          </div>
        </>
      )}
    </div>
  );
}
